"use strict";(globalThis.webpackChunkhabitforge_docs=globalThis.webpackChunkhabitforge_docs||[]).push([[9056],{826(e){e.exports=JSON.parse('{"tag":{"label":"habits","permalink":"/docs/tags/habits","allTagsPath":"/docs/tags","count":5,"items":[{"id":"habits/check-ins-and-streaks","title":"Check-ins and streaks","description":"A check-in tells HabitForge you did a habit today. Consecutive check-ins build a streak and earn points, and your longest streak is kept even when a run breaks.","permalink":"/docs/habits/check-ins-and-streaks"},{"id":"habits/create","title":"Create a habit","description":"Create a habit with a name, category, kind and schedule, plus the optional cue, routine, reward, craving and investment fields from The Power of Habit.","permalink":"/docs/habits/create"},{"id":"habits/levels-and-points","title":"Levels and points","description":"Points come from check-ins and achievements across all your habits, and enough of them raise your level through ten forge tiers, from Spark to Forge Master.","permalink":"/docs/habits/levels-and-points"},{"id":"habits/manage","title":"Manage habits","description":"Edit a habit\'s details, pause it while you are away, or delete it for good. Pausing keeps your history; deleting removes the habit permanently.","permalink":"/docs/habits/manage"},{"id":"habits/rope-strength","title":"Rope strength","description":"HabitForge\'s habit-strength meter. The rope thickens from a thread towards a chain as you keep going, and frays where you stopped. Calculated, not predicted.","permalink":"/docs/habits/rope-strength"}],"unlisted":false}}')}}]);